class CRMLead {
    setup() {
        if (!this._originalDocumentContext.fieldPropertyOverrides) {
            this._originalDocumentContext.fieldPropertyOverrides = {};
        }
        this._originalDocumentContext.fieldPropertyOverrides['chat_summary'] = {
            fieldtype: 'HTML',
            options: '<div class="text-sm text-ink-gray-9 leading-relaxed">{{ chat_summary }}</div>'
        };
    }
}
